"""Generate the 9 Demak gate configs (3 seeds x best/last/swa5) on the VM.

Resolves each arm's checkpoint by GLOB against the real seed dir so no filename
is hardcoded; refuses to emit a config for an arm whose checkpoint is missing.
"""
from pathlib import Path
import sys

MODEL = "upernet_tu-swin_base_patch4_window7_224"
STAGE2 = Path("outputs/stage2") / MODEL
SEEDS = ["s19", "s42", "s58"]
OUT = Path("/home/noel/configs/demak_gate")

TEMPLATE = """\
# Demak concurrent gate — Swin-B stage2, seed {seed}, arm "{arm}".
# Generated by gen_gate_configs.py. Preset native224_weighted_224_b0_s32 is the
# canonical comparison baseline (tile 224, buffer 0, stride 32, hann blend).

sweep:
  name: "gate_{arm}_demak_{seed}"
  dry_run: false
  continue_on_error: true

  input_dir: "/home/noel/data_demak_concurrent"
  input_glob: "S1_*.tif"

  common_overrides:
    inference.post_processing.smoothing.apply_simplification: true
    inference.post_processing.smoothing.simplify_tolerance_meters: 1.0
    inference.post_processing.filtering.apply_length_filter: true
    inference.post_processing.filtering.min_length_meters: 10000.0
    inference.data.edge_policy: "shift_inward"
    inference.stitching.min_weight: 0.001
    inference.data.num_workers: 8
    inference.data.batch_size: 256
    inference.output.probability_precision: "float16"

  checkpoints:
    - name: "upernet_swin_base_224_{arm}"
      checkpoint_path: "{ckpt}"
      model:
        arch: "upernet"
        encoder_name: "tu-swin_base_patch4_window7_224"

  presets:
    - name: "native224_weighted_224_b0_s32"
      overrides:
        inference.data.tile_size: 224
        inference.data.buffer_size: 0
        inference.data.stride: 32
        inference.stitching.mode: "weighted_blend"
        inference.stitching.blend_window: "hann"
"""


def resolve(seed_dir: Path, arm: str) -> Path | None:
    if arm == "best":
        p = seed_dir / "best.pth"
        return p if p.exists() else None
    if arm == "last":
        c = sorted(seed_dir.glob("*_last.pth"))
    elif arm == "swa5":
        c = sorted(seed_dir.glob("*_swa5_step*.pth"))
    else:
        raise ValueError(arm)
    if len(c) != 1:
        print("  !! %s/%s: expected 1 match, got %d" % (seed_dir.name, arm, len(c)))
        return None
    return c[0]


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    written, missing = [], []
    for seed in SEEDS:
        seed_dir = STAGE2 / seed
        for arm in ["best", "last", "swa5"]:
            ckpt = resolve(seed_dir, arm)
            if ckpt is None:
                missing.append("%s/%s" % (seed, arm))
                continue
            # best.pth is a symlink; record the RESOLVED target for provenance.
            real = ckpt.resolve().relative_to(Path.cwd()) if ckpt.is_symlink() else ckpt
            cfg = OUT / ("gate_%s_demak_%s.yaml" % (arm, seed))
            cfg.write_text(TEMPLATE.format(seed=seed, arm=arm, ckpt=str(real)))
            written.append((cfg.name, str(real)))
    print("=== WROTE %d configs ===" % len(written))
    for name, ck in written:
        print("  %-32s -> %s" % (name, ck.split("/")[-1]))
    if missing:
        print("=== MISSING ARMS (no config written): %s ===" % ", ".join(missing))
        sys.exit(1)


if __name__ == "__main__":
    main()
